ALTER TABLE storage_version DROP CONSTRAINT storage_version_purpose_check;
ALTER TABLE storage_version ADD CONSTRAINT storage_version_purpose_check CHECK(purpose IN('SYNTHETIC_ORIGINAL','SYNTHETIC_WORKER_ARTIFACT','SYNTHETIC_RESULT_ARTIFACT'));
CREATE TABLE ai_result(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES ai_task(id),request_id uuid NOT NULL,scope_id uuid NOT NULL,hospital_id uuid NOT NULL REFERENCES hospital(id),scan_id uuid NOT NULL REFERENCES scan_import(id),owner_id uuid NOT NULL REFERENCES app_user(id),task_version bigint NOT NULL,source_hash text NOT NULL CHECK(source_hash~'^[a-f0-9]{64}$'),binding jsonb NOT NULL CHECK(jsonb_typeof(binding)='object'),generator text NOT NULL CHECK(generator='SYN-OVERLAY-1'),artifact_hash text NOT NULL CHECK(artifact_hash~'^[a-f0-9]{64}$'),artifact_size bigint NOT NULL CHECK(artifact_size BETWEEN 25 AND 65536),artifact_id uuid REFERENCES storage_version(id),state text NOT NULL DEFAULT 'BUILDING' CHECK(state IN('BUILDING','READY')),version bigint NOT NULL DEFAULT 0 CHECK(version IN(0,1)),created_at timestamptz NOT NULL DEFAULT statement_timestamp(),UNIQUE(task_id,generator),FOREIGN KEY(request_id,scope_id) REFERENCES request_workflow(request_id,scope_id),CHECK((state='BUILDING' AND version=0 AND artifact_id IS NULL) OR (state='READY' AND version=1 AND artifact_id IS NOT NULL)));
CREATE INDEX idx_ai_result_scan ON ai_result(request_id,scan_id,created_at DESC);
CREATE FUNCTION guard_ai_result() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Result history is retained' USING ERRCODE='23514';END IF;
 IF TG_OP='INSERT' THEN
  IF NOT EXISTS(SELECT 1 FROM ai_task t WHERE t.id=NEW.task_id AND t.request_id=NEW.request_id AND t.scope_id=NEW.scope_id AND t.hospital_id=NEW.hospital_id AND t.scan_id=NEW.scan_id AND t.owner_id=NEW.owner_id AND t.state='SYNTHETIC_SUCCEEDED' AND t.version=NEW.task_version) THEN RAISE EXCEPTION 'Result source mismatch' USING ERRCODE='23514';END IF;
 ELSE
  IF ROW(NEW.id,NEW.task_id,NEW.request_id,NEW.scope_id,NEW.hospital_id,NEW.scan_id,NEW.owner_id,NEW.task_version,NEW.source_hash,NEW.binding,NEW.generator,NEW.artifact_hash,NEW.artifact_size,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.task_id,OLD.request_id,OLD.scope_id,OLD.hospital_id,OLD.scan_id,OLD.owner_id,OLD.task_version,OLD.source_hash,OLD.binding,OLD.generator,OLD.artifact_hash,OLD.artifact_size,OLD.created_at) OR OLD.state<>'BUILDING' OR NEW.state<>'READY' OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Result immutable version' USING ERRCODE='23514';END IF;
 END IF;
 IF NEW.artifact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM storage_version v WHERE v.id=NEW.artifact_id AND v.request_id=NEW.request_id AND v.hospital_id=NEW.hospital_id AND v.purpose='SYNTHETIC_RESULT_ARTIFACT' AND v.state='READY' AND v.sha256=NEW.artifact_hash AND v.byte_size=NEW.artifact_size) THEN RAISE EXCEPTION 'Result artifact mismatch' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_ai_result BEFORE INSERT OR UPDATE OR DELETE ON ai_result FOR EACH ROW EXECUTE FUNCTION guard_ai_result();
